#include <cstdio>
#include <cstring>
#include <cmath>
#include <cstdlib>
#include <vector>
#include <string>
#include <algorithm>
#include <queue>
#include <stack>
#include <deque>
#include <map>
#include <set>
#include <unordered_map>
#include <unordered_set>
#include <functional>
#include <numeric>
#include <sstream>
#include <iostream>
using namespace std;
int main(){int n,m;scanf("%d %d",&n,&m);
vector<vector<int>>rev(n+1);
for(int i=0;i<m;++i){int u,v;scanf("%d %d",&u,&v);rev[v].push_back(u);}
for(int i=1;i<=n;++i){sort(rev[i].begin(),rev[i].end());
printf("%d",(int)rev[i].size());
for(int v:rev[i])printf(" %d",v);
printf("\n");}
return 0;}

